use crate::{jc028 as b,model::*,unit_support::*};
fn settle(g:&mut Game){for _ in 0..80{if g.pending.is_some()||g.stack.is_empty(){return;}crate::jc029_tests::pass_top(g);}panic!()}
#[test]fn jc028_real_paid_entry_sacrifice_and_blood_form(){assert_current_serial_catalog();let mut g=game();fund(&mut g,0,"JC029",2);let host=field(&mut g,"JC029",0);let id=held(&mut g,b::ID,0);act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("deploy")});settle(&mut g);let id=g.regions[0].cards.iter().find(|c|c.definition==b::ID).unwrap().id.clone();act(&mut g,0,Action{card_id:Some(id),ability_id:Some(b::KEY.into()),target_id:Some(host.clone()),..Action::new("activate")});settle(&mut g);assert_eq!(g.attachments.len(),1);assert_eq!(g.attachments[0].card.definition,b::FORM);assert_eq!(g.attachments[0].host_id,host);restore(&mut g);}
fn activated()->(Game,String,String){let mut g=game();let host=field(&mut g,"JC029",0);let source=field(&mut g,b::ID,0);act(&mut g,0,Action{card_id:Some(source.clone()),ability_id:Some(b::KEY.into()),target_id:Some(host.clone()),..Action::new("activate")});(g,source,host)}
fn formed()->(Game,String){let(mut g,_,host)=activated();settle(&mut g);(g,host)}
fn bad(g:&Game,x:&Game){assert!(Game::from_persisted(&serde_json::to_string(x).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(g);r.game=x.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn jc028_form_keeps_printed_identity_and_has_only_host_buff(){let(g,host)=formed();let a=&g.attachments[0];let c=&a.card;assert!(c.blood_origin.is_some());let d=crate::catalog::card(&c.definition);assert_eq!(d.id,b::ID);assert_eq!(d.name,"鲜血");assert_eq!(d.kind,"attachment");assert_eq!(d.cost,1);assert_eq!(d.loyalty,vec!["蓝色"]);assert_eq!(d.magic,"鲜血");assert_eq!(d.defense,None);assert_eq!(d.permanent_icons,Icons::default());assert!(crate::rules::definition(b::FORM).abilities.is_empty());let h=g.board(&host).unwrap().1;let mut bare=g.clone();bare.attachments.clear();assert_eq!(g.defense(h,0),bare.defense(h,0)+1);assert_eq!(g.current_icons(h,0).combat,bare.current_icons(h,0).combat+1);let view=g.card_view(c,0,Some(0),Some("attachment"));assert_eq!(view.card_id.as_deref(),Some(b::ID));assert_eq!(view.name,"鲜血");assert!(!g.legal_actions(0).iter().any(|a|a.action.card_id.as_deref()==Some(&c.id)&&a.action.ability_id.as_deref()==Some(b::KEY)));}
#[test]fn jc028_target_hidden_or_gone_fizzles_after_actual_cost(){for hidden in [false,true]{let(mut g,_,host)=activated();if hidden{g.hide_in_place_successor(&host).unwrap();}else{g.return_hand(&host);}settle(&mut g);assert!(g.attachments.is_empty());assert_eq!(g.players[0].graveyard.iter().filter(|c|c.definition==b::ID).count(),1);restore(&mut g);}}
#[test]fn jc028_original_grave_entity_removed_never_substitutes_same_name(){let(mut g,_,_)=activated();let i=g.players[0].graveyard.iter().position(|c|c.definition==b::ID).unwrap();let c=g.take_grave_observed(0,i);let c=g.reset_zone_card(c);g.players[0].hand.push(c);let another=g.make_card(b::ID,0);g.players[0].graveyard.push(another);settle(&mut g);assert!(g.attachments.is_empty());assert_eq!(g.players[0].graveyard.iter().filter(|c|c.definition==b::ID).count(),1);restore(&mut g);}
#[test]fn jc028_self_target_pays_but_does_not_attach_to_departed_self(){let mut g=game();let id=field(&mut g,b::ID,0);act(&mut g,0,Action{card_id:Some(id.clone()),ability_id:Some(b::KEY.into()),target_id:Some(id),..Action::new("activate")});settle(&mut g);assert!(g.attachments.is_empty());assert_eq!(g.players[0].graveyard.len(),1);}
#[test]fn jc028_owner_controller_enemy_host_and_host_move_are_distinct(){let mut g=game();let host=field(&mut g,"JC029",2);let id=field(&mut g,b::ID,1);g.board_mut(&id).unwrap().controller=0;act(&mut g,0,Action{card_id:Some(id),ability_id:Some(b::KEY.into()),target_id:Some(host.clone()),..Action::new("activate")});let i=g.regions[0].cards.iter().position(|c|c.id==host).unwrap();let c=g.regions[0].cards.remove(i);g.regions[1].cards.push(c);settle(&mut g);assert_eq!(g.attachments[0].card.owner,1);assert_eq!(g.attachments[0].card.controller,0);assert_eq!(g.attachment_region(&g.attachments[0]),Some(1));restore(&mut g);let id=g.attachments[0].card.id.clone();g.return_hand(&id);let c=g.players[1].hand.iter().find(|c|c.definition==b::ID).unwrap();assert_eq!(c.controller,1);assert!(c.blood_origin.is_none());restore(&mut g);}
#[test]fn jc028_leave_hand_grave_and_seal_reset_to_printed_character(){for mode in 0..3{let(mut g,host)=formed();let id=g.attachments[0].card.id.clone();match mode{0=>g.return_hand(&id),1=>g.return_hand(&host),_=>{let(_,c)=g.leave_in_play(&id).unwrap();g.seal_card_on_valid_host(c,0,"society:p0");}}assert!(g.attachments.is_empty());let c=match mode{0=>g.players[0].hand.iter().find(|c|c.definition==b::ID).unwrap(),1=>g.players[0].graveyard.iter().find(|c|c.definition==b::ID).unwrap(),_=>&g.sealed_cards[0].card};assert_eq!(c.definition,b::ID);assert!(c.blood_origin.is_none());restore(&mut g);}}
#[test]fn jc028_form_provenance_corruption_and_wrong_zone_rejected(){let(g,_)=formed();for n in 0..5{let mut x=g.clone();match n{0=>x.attachments[0].card.blood_origin=None,1=>x.attachments[0].card.blood_origin.as_mut().unwrap().owner=1,2=>x.attachments[0].card.definition=b::ID.into(),3=>{let c=x.attachments.remove(0).card;x.players[0].hand.push(c);},_=>{let mut a=x.attachments[0].clone();a.card.id=x.id();x.attachments.push(a);}}bad(&g,&x);}}
#[test]fn jc028_paid_frame_and_missing_transaction_frame_rejected(){let(g,_,_)=activated();for n in 0..4{let mut x=g.clone();let f=x.stack.last_mut().unwrap().frame.as_mut().unwrap();match n{0=>f.already_paid.clear(),1=>f.source.card.definition="JC029".into(),2=>{let PaidCost::JC028Sacrificed(p)=&mut f.already_paid[0]else{panic!()};p.old_instance=p.grave_instance.clone();},_=>f.targets[0].spec.subtype=None}bad(&g,&x);}let mut x=g.clone();x.stack.push(x.stack[0].clone());bad(&g,&x);}
#[test]fn jc028_nonvampire_and_wrong_seat_reject_before_sacrifice(){let mut g=game();let id=field(&mut g,b::ID,0);let target=field(&mut g,"JC125",0);let a=Action{card_id:Some(id),ability_id:Some(b::KEY.into()),target_id:Some(target),..Action::new("activate")};reject(&mut g,0,a.clone());reject(&mut g,1,a);assert!(g.players[0].graveyard.is_empty());}
#[test]fn jc028_real_attachment_event_reaches_bq030_observer(){let mut g=game();field(&mut g,"BQ030",0);let host=field(&mut g,"JC029",0);let id=field(&mut g,b::ID,0);act(&mut g,0,Action{card_id:Some(id),ability_id:Some(b::KEY.into()),target_id:Some(host),..Action::new("activate")});settle(&mut g);assert_eq!(g.attachments.len(),1);restore(&mut g);assert!(g.pending.is_some()||!g.effects.is_empty());}
use crate::{catalog,abi112_review_play_tests::Trace};
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert!(!d.changed&&d.journal.is_empty());assert_eq!(d.state,s["expected"]["state"]);s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn construct(seed:u64)->Game{use crate::deck;let mut d=deck::preset("watchers").unwrap();d.id="jc028-natural".into();d.society_id=None;d.core_card_id=None;d.cards=[(b::ID,3),("JC029",3),("JC030",3),("JC125",41)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();for c in &mut cards{if c.id==b::ID{c.supported=true;}}let d=deck::validate_with_cards(d,&cards).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("jc028".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
fn initial_choice(g:&Game)->Vec<String>{let p=g.pending.as_ref().unwrap();let mut opts=p.choice.options.iter().collect::<Vec<_>>();opts.sort_by_key(|o|g.players[p.seat].hand.iter().any(|c|c.id==o.id&&[b::ID,"JC029","JC030"].contains(&c.definition.as_str())));opts.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()}
fn natural()->serde_json::Value{let seed=(1..10000).find(|seed|{let mut g=construct(*seed);for _ in 0..40{if g.pending.is_some(){let ids=initial_choice(&g);choose(&mut g,ids);}else if g.legal_actions(0).iter().any(|a|a.action.kind=="asset"){break;}else{let Some(s)=(0..4).find(|s|g.legal_actions(*s).iter().any(|a|a.action.kind=="pass"))else{return false;};g.apply(s,Action::new("pass")).unwrap();}}[b::ID,"JC029"].iter().all(|id|g.players[0].hand.iter().any(|c|&c.definition==id))&&g.players[0].hand.iter().filter(|c|catalog::card(&c.definition).color=="蓝").count()>=4}).expect("legal seed");let g=construct(seed);let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"jc028-natural-fifty-vampire-entry-sacrifice-blood".into(),891);let(mut host,mut source,mut converted)=(false,false,false);for _ in 0..1600{if let Some(p)=t.room.game.pending.clone(){if matches!(&p.resolution,ChoiceResolution::Forecast{..}|ChoiceResolution::Frame{choice:FrameChoice::Forecast{..},..}){let top=p.choice.options.iter().map(|o|o.id.clone()).collect();t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(top),bottom:Some(vec![]),..Action::new("choose")});continue;}t.choose(initial_choice(&t.room.game));continue;}if converted&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}if !t.room.game.stack.is_empty(){t.pass();continue;}let g=&t.room.game;let legal=g.legal_actions(0);let a=if source{let h=g.regions.iter().flat_map(|r|&r.cards).find(|c|c.controller==0&&c.definition=="JC029").unwrap();legal.iter().find(|a|a.action.ability_id.as_deref()==Some(b::KEY)&&a.action.target_id.as_deref()==Some(&h.id))}else if g.players[0].assets.len()>=3&&g.players[0].assets.iter().filter(|c|catalog::card(&c.definition).color=="蓝").count()>=2{legal.iter().find(|a|a.action.kind=="deploy"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==if host{b::ID}else{"JC029"})))}else{let keep=[b::ID,"JC029"].iter().filter_map(|id|g.players[0].hand.iter().find(|c|&c.definition==id).map(|c|&c.id)).collect::<Vec<_>>();legal.iter().filter(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|!keep.contains(&id))).min_by_key(|a|g.players[0].hand.iter().find(|c|Some(&c.id)==a.action.card_id.as_ref()).map_or(true,|c|catalog::card(&c.definition).color!="蓝"))};if let Some(a)=a{if a.action.kind=="deploy"{if host{source=true;}else{host=true;}}if a.action.ability_id.as_deref()==Some(b::KEY){converted=true;}t.action(0,a.action.clone());}else{t.pass();}}assert!(host&&source&&converted,"seed={seed} host={host} source={source} converted={converted}");assert_eq!(t.room.game.attachments.iter().filter(|a|a.card.definition==b::FORM).count(),1);let mut v=t.value();v["construction"]=serde_json::json!({"seed":seed,"deck":deck,"ordinaryCards":50,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true});duplicate(v)}
fn prepared()->serde_json::Value{let mut g=game();let host=field(&mut g,"JC029",0);let source=field(&mut g,b::ID,0);fund(&mut g,0,"JC005",2);let destroy=held(&mut g,"JC005",0);let mut t=Trace::new_preserving_rng(g,"jc028-prepared-real-conversion-and-disintegrate".into(),892);t.action(0,Action{card_id:Some(source),ability_id:Some(b::KEY.into()),target_id:Some(host),..Action::new("activate")});while !t.room.game.stack.is_empty(){t.pass();}let blood=t.room.game.attachments[0].card.id.clone();t.action(0,Action{card_id:Some(destroy),target_id:Some(blood),..Action::new("play")});while !t.room.game.stack.is_empty(){t.pass();}assert!(t.room.game.attachments.is_empty());assert!(t.room.game.players[0].graveyard.iter().any(|c|c.definition==b::ID&&c.blood_origin.is_none()));duplicate(t.value())}
#[test]fn jc028_native_natural_and_removal_export(){let cases=vec![natural(),prepared()];let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/jc028.rs",include_bytes!("jc028.rs").as_slice()),("rust-game/src/jc028_tests.rs",include_bytes!("jc028_tests.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(p)=std::env::var("JC028_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}
