#[test]fn jc028_forged_face_down_attachment_is_not_a_character_hide_entry(){let(g,_)=formed();let mut x=g.clone();x.attachments[0].card.face_down=true;bad(&g,&x);}
#[test]fn jc028_actual_host_hide_buries_attachment_and_clears_form(){let(mut g,host)=formed();g.hide_in_place_successor(&host).unwrap();assert!(g.attachments.is_empty());let c=g.players[0].graveyard.iter().find(|c|c.definition==b::ID).unwrap();assert!(c.blood_origin.is_none());restore(&mut g);}
#[test]fn jc028_extra_payload_cannot_pay_and_sacrifice(){let mut g=game();let host=field(&mut g,"JC029",0);let source=field(&mut g,b::ID,0);reject(&mut g,0,Action{card_id:Some(source),ability_id:Some(b::KEY.into()),target_id:Some(host),amount:Some(99),..Action::new("activate")});assert!(g.players[0].graveyard.is_empty());}

#[test]fn jc028_historical_form_provenance_must_match_live_entity(){let(g,_)=formed();let mut c=g.attachments[0].card.clone();let o=c.blood_origin.as_mut().unwrap();let n=o.old_instance.strip_prefix('i').unwrap().parse::<u64>().unwrap();o.old_instance=format!("i{}",n-1);assert!(g.mobility_immutable_identity(&c).is_err());}
